func altSafePath(name string) bool {
    // Could path.Clean + path.IsAbs replace containsDotDot?
    cleaned := path.Clean(name)
    if path.IsAbs(cleaned) { return false }
    if strings.HasPrefix(cleaned, "..") { return false }
    if cleaned != name { return false } // catches embedded ..
